// Razor view — encoding is the default
<p>@Model.UserComment</p>            // &lt;script&gt;alert(1)&lt;/script&gt; → text, harmless
<p>@Html.Raw(Model.UserComment)</p>  // DANGEROUS — renders live markup

// Allow-listed sanitization for fields that legitimately contain HTML
using Ganss.Xss;
var sanitizer = new HtmlSanitizer();
sanitizer.AllowedTags.Add("mark");           // explicit allow-list
var safeHtml = sanitizer.Sanitize(untrustedComment);

// Content-Security-Policy as defense in depth
app.Use(async (context, next) =>
{
    context.Response.Headers.Append(
        "Content-Security-Policy",
        "default-src 'self'; script-src 'self'; object-src 'none'; base-uri 'self'");
    await next();
});

